command:
"C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$planner = Get-Content -Encoding utf8 -Raw 7c829ae6_planner.json | ConvertFrom-Json
$html = '"'output/index.html'
"'$items = New-Object System.Collections.Generic.List[object]
foreach ($section in $planner.sections) {
  foreach ($question in $section.questions) {
    if ($question.prompt) { $items.Add([pscustomobject]@{kind='"'prompt'; id="'$question.id; text=[string]$question.prompt}) }
    foreach ($choice in $question.choices) { if ($choice.label) { $items.Add([pscustomobject]@{kind='"'choice'; id="'$question.id; text=[string]$choice.label}) } }
    if ($question.answer) { $items.Add([pscustomobject]@{kind='"'answer'; id="'$question.id; text=[string]$question.answer}) }
    if ($question.feedback.correct) { $items.Add([pscustomobject]@{kind='"'feedback.correct'; id="'$question.id; text=[string]$question.feedback.correct}) }
    if ($question.feedback.wrong) { $items.Add([pscustomobject]@{kind='"'feedback.wrong'; id="'$question.id; text=[string]$question.feedback.wrong}) }
  }
  foreach ($element in $section.elements) {
    foreach ($rendered in $element.rendered_text) { if ($rendered) { $items.Add([pscustomobject]@{kind='"'rendered_text'; id="'$section.id; text=[string]$rendered}) } }
  }
}
$results = foreach ($item in $items) {
  $count = & grep -cF -- $item.text $html
  [pscustomobject]@{kind=$item.kind; id=$item.id; count=[int]$count; text=$item.text}
}
"TOTAL_CHECKLIST_ITEMS=$($results.Count)"
"ZERO_COUNT=$(@($results | Where-Object count -eq 0).Count)"
$results | Where-Object count -eq 0 | Format-Table -AutoSize -Wrap
"QUESTION_ID_ZERO_COUNT=$(@($planner.sections.questions.id | Where-Object { $qid=$_; [int](& grep -cF -- $qid $html) -eq 0 }).Count)"'
